These building blocks cover most production LLM systems. They compose freely: a router can send work to an orchestrator, which can use evaluator loops inside its workers. 1 · Prompt chaining Fixed sequence; each step's output feeds the next. Checks between steps catch problems early. Use for: outline → draft → edit; extract → translate. 2 · Routing Classify first, then handle with a specialised prompt or model. Use for: support triage; sending easy questions to a small model. 3 · Parallelization Sectioning: independent sub-tasks at once. Voting: the same task N times, then take the majority. Use for: multi-aspect reviews; high-stakes classification. 4 · Orchestrator–workers Like parallelization, but the model decides the sub-tasks at runtime. Use for: research, multi-file changes where the files aren't known in advance. 5 · Evaluator–optimizer One call generates, another grades against explicit criteria, and the loop repeats until it passes (bounded). Use for: translation quality, code that must meet a spec, writing with a rubric. All five patterns in code One file, one function per pattern. Note where your code owns the control flow (gates, routes, vote counting, round limits). That's what makes these workflows and not agents. """The five workflow patterns. Your code owns the control flow; the model fills in steps.""" import asyncio import json from collections import Counter import anthropic client = anthropic.Anthropic() aclient = anthropic.AsyncAnthropic() SMART, FAST = "claude-opus-5-5", "claude-haiku-5-5" def text_of(response) -> str: return "".join(b.text for b in response.content if b.type == "text") def ask(system: str, prompt: str, model: str = SMART) -> str: r = client.messages.create(model=model, max_tokens=16000, system=system, messages=[{"role": "user", "content": prompt}]) return text_of(r) def ask_json(system: str, prompt: str, schema: dict, model: str = SMART) -> dict: """Structured output: the reply is guaranteed to match `schema`.""" r = client.messages.create( model=model, max_tokens=16000, system=system, output_config={"format": {"type": "json_schema", "schema": schema}}, messages=[{"role": "user", "content": prompt}], ) return json.loads(text_of(r)) # 1. Prompt chaining: fixed steps, with a programmatic gate between them ------------ def launch_post(product_notes: str) -> str: outline = ask("You write product marketing.", f"Write a 5-bullet outline (one '- ' bullet per line) for:
{product_notes}") if sum(line.startswith("- ") for line in outline.splitlines()) < 5: # gate raise ValueError("Outline gate failed; not worth spending tokens on a draft.") draft = ask("You write product marketing.", f"Expand into a 300-word post:
{outline}") return ask("You are a strict copy editor. Return only the edited post.", draft) # 2. Routing: classify once, then send to a specialised prompt (or cheaper model) --- ROUTES = { "billing": "You are a billing specialist. Be precise about amounts and dates.", "technical": "You are a senior support engineer. Ask for logs if needed.", "general": "You are a friendly support agent.", } ROUTE_SCHEMA = { "type": "object", "properties": {"category": {"type": "string", "enum": list(ROUTES)}}, "required": ["category"], "additionalProperties": False, } def handle_ticket(ticket: str) -> str: category = ask_json("Classify the support ticket.", ticket, ROUTE_SCHEMA, model=FAST)["category"] return ask(ROUTES[category], ticket) # 3a. Parallelization, sectioning: independent sub-tasks at the same time ----------- async def review_diff(diff: str) -> dict[str, str]: focuses = { "security": "Review ONLY for security issues.", "performance": "Review ONLY for performance issues.", "tests": "Review ONLY for missing or weak tests.", } async def one(name: str, system: str) -> tuple[str, str]: r = await aclient.messages.create(model=SMART, max_tokens=16000, system=system, messages=[{"role": "user", "content": diff}]) return name, text_of(r) return dict(await asyncio.gather(*(one(n, s) for n, s in focuses.items()))) # 3b. Parallelization, voting: same question N times, take the majority ------------ async def is_phishing(email: str, votes: int = 3) -> bool: async def vote() -> str: r = await aclient.messages.create( model=FAST, max_tokens=256, system="Answer with exactly one word: PHISHING or SAFE.", messages=[{"role": "user", "content": email}]) return text_of(r).strip().upper() tally = Counter(await asyncio.gather(*(vote() for _ in range(votes)))) return tally["PHISHING"] > votes // 2 # 4. Orchestrator-workers: the model decides the sub-tasks at runtime --------------- PLAN_SCHEMA = { "type": "object", "properties": {"subtasks": {"type": "array", "items": { "type": "object", "properties": {"title": {"type": "string"}, "instructions": {"type": "string"}}, "required": ["title", "instructions"], "additionalProperties": False, }}}, "required": ["subtasks"], "additionalProperties": False, } async def research(goal: str) -> str: plan = ask_json("Split the goal into 2-5 independent research sub-tasks.", goal, PLAN_SCHEMA) async def worker(task: dict) -> str: # fresh, isolated context per worker r = await aclient.messages.create( model=FAST, max_tokens=16000, system="Complete the sub-task. Reply with a dense summary under 200 words.", messages=[{"role": "user", "content": f"{task['title']}

{task['instructions']}"}]) return f"## {task['title']}
{text_of(r)}" findings = await asyncio.gather(*(worker(t) for t in plan["subtasks"])) return ask("Synthesize the findings into one answer. Cite sub-task titles.", f"Goal: {goal}

" + "

".join(findings)) # 5. Evaluator-optimizer: generate, grade against criteria, revise ----------------- VERDICT_SCHEMA = { "type": "object", "properties": {"passed": {"type": "boolean"}, "feedback": {"type": "string"}}, "required": ["passed", "feedback"], "additionalProperties": False, } def write_with_review(task: str, criteria: str, max_rounds: int = 3) -> str: draft = ask("You are a technical writer.", task) for _ in range(max_rounds): # bounded: the loop must end verdict = ask_json(f"You are a demanding reviewer. Criteria:
{criteria}", draft, VERDICT_SCHEMA) if verdict["passed"]: break draft = ask("You are a technical writer.", f"{task}

Previous draft:
{draft}

Reviewer feedback:
{verdict['feedback']}" "

Rewrite the draft to address every point.") return draft 💡 Design notes from the code Structured outputs (output_config.format) make routing and grading reliable. You parse guaranteed JSON instead of hoping the model said "billing". Cheap models for narrow jobs: the router, voters, and workers use claude-haiku-5-5; planning and synthesis use claude-opus-5-5. Every loop is bounded (max_rounds), and every gate fails loudly.

A helpdesk server exposing all three server primitives. Type hints plus Annotated[…, Field(description=…)] become the input schema. Note the per-parameter descriptions, the Literal enum, and the bounds on limit. """A small MCP server exposing a tool, a resource template and a prompt (MCP Python SDK 2.x).""" from typing import Annotated, Literal from mcp.server.mcpserver import MCPServer from mcp.types import ToolAnnotations from pydantic import Field mcp = MCPServer("helpdesk", instructions="Tools for searching and reading support tickets.") TICKETS = { "T-1": {"title": "Login fails with SSO", "status": "open", "body": "SAML assertion expired..."}, "T-2": {"title": "Invoice shows wrong VAT", "status": "closed", "body": "VAT rate was 19%..."}, } @mcp.tool(annotations=ToolAnnotations(read_only_hint=True, open_world_hint=False)) def search_tickets( query: Annotated[str, Field(description="Keyword to match in the title, case-insensitive.")], status: Annotated[Literal["open", "closed", "any"], Field(description="Filter by status.")] = "any", limit: Annotated[int, Field(ge=1, le=50, description="Max tickets to return.")] = 10, ) -> list[dict]: """Search support tickets by keyword. Returns id, title and status for each match. Use ticket://{id} to read the full text of one ticket.""" hits = [ {"id": tid, "title": t["title"], "status": t["status"]} for tid, t in TICKETS.items() if query.lower() in t["title"].lower() and status in ("any", t["status"]) ] return hits[:limit] @mcp.resource("ticket://{ticket_id}", mime_type="text/markdown") def ticket(ticket_id: str) -> str: """Full text of one ticket. The host app decides when to attach it.""" t = TICKETS[ticket_id] return f"# {ticket_id}: {t['title']}

Status: {t['status']}

{t['body']}" @mcp.prompt() def triage(ticket_id: str) -> str: """User-invoked template: triage a ticket.""" return f"Read ticket://{ticket_id}, classify severity (P1-P4) and propose next steps." if __name__ == "__main__": mcp.run() # stdio transport by default; use mcp.run("streamable-http") for remote ⚠️ SDK version noteIn MCP Python SDK 2.x, the high-level server class is MCPServer (from mcp.server.mcpserver import MCPServer). Older tutorials use 1.x's FastMCP (mcp.server.fastmcp), which 2.x no longer ships. A docstring's Args: section does not become per-parameter descriptions. Use Annotated + Field. Try it interactively: npx @modelcontextprotocol/inspector python mcp_server.py opens the MCP Inspector, a UI that lists tools, resources, and prompts and lets you call them by hand. Use it before you connect a model.
